) as v(slug, cat, name_bn, name_en, unit_bn, description, origin, season, moq, famous) join categories c on c.slug = v.cat left join districts fd on fd.name_bn = v.famous
on conflict (slug) do nothing;

insert into service_areas (district_id, note)
select d.id, 'Sylhet-first launch' from districts d join divisions v on v.id = d.division_id where v.name_en = 'Sylhet'
on conflict (district_id) do nothing;

insert into markets (slug, name_bn, district_id)
select v.slug, v.name_bn, d.id from (values
  ('karwan-bazar', 'কারওয়ান বাজার', 'ঢাকা'),
  ('reza-bazar', 'রেয়াজউদ্দিন বাজার', 'চট্টগ্রাম'),
  ('kazir-bazar', 'কাজীর বাজার', 'সিলেট'),
  ('rajshahi-bazar', 'সাহেব বাজার', 'রাজশাহী')
) as v(slug, name_bn, city) join districts d on d.name_bn = v.city
on conflict (slug) do nothing;

